## 1️⃣ `db.php` — Conexão com banco

```php
<?php
define('HOST', 'localhost');
define('USER', 'root');
define('PASS', '');
define('DB', 'chatapp');

try {
    $pdo = new PDO("mysql:host=".HOST.";dbname=".DB, [
        PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION,
        PDO::ATTR_DEFAULTFETCHKEY => 'id'
    ]);
    $pdo->setAttribute('charset', 'utf8mb4');
} catch (Exception $e) {
    die("Erro de conexão: " . $e->getMessage());
}

// Funções auxiliares
function checkSession(): bool {
    return isset($_SESSION['user_id']);
}
function currentUser(): ?int {
    return $_SESSION['user_id'] ?? null;
}
function requireLogin(): void {
    if (!checkSession()) {
        header("location: index.php");
        exit;
    }
}
function getUsuario(): array|null {
    $id = currentUser();
    if ($id === null) return null;
    $stmt = $pdo->query("SELECT * FROM usuarios WHERE id = :id");
    $row = $stmt->fetch(PDO::FETCH_ASSOC);
    return $row ?: null;
}
?>
```

### Schema SQL (`schema.sql`)

```sql
CREATE DATABASE IF NOT EXISTS chatapp CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE chatapp;

CREATE TABLE usuarios (
    id INT AUTO_INCREMENT PRIMARY KEY,
    nome VARCHAR(100) NOT NULL,
    email VARCHAR(150) UNIQUE NOT NULL,
    senha_hash VARCHAR(255) NOT NULL,
    ativo BOOLEAN DEFAULT 1,
    criado_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE conversas (
    id INT AUTO_INCREMENT PRIMARY KEY,
    usuario_id INT NOT NULL,
    remetente_id INT NOT NULL,
    mensagem TEXT NOT NULL,
    lida BOOLEAN DEFAULT 0,
    criado_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (usuario_id) REFERENCES usuarios(id),
    FOREIGN KEY (remetente_id) REFERENCES usuarios(id)
);

CREATE INDEX idx_conversas_usuario ON conversas(usuario_id);
CREATE INDEX idx_conversas_rem on conversas(remetente_id);
```

