<script>
const url = window.location.href.split('?')[0];
let userId = null;
let conversaAtual = null;

// Abre conversa se houver parâmetro
const params = new URLSearchParams(url.search);
userId = parseInt(params.get('id') || '', 10);
if(userId){
  const el = document.querySelector(`[data-user-id="${userId}"]`);
  if(el){ el.click(); }
}

function carregarMensagens(uid){
  fetch(`chat.php?acao=listar&id=${uid}&_t=${Date.now()}`, {credentials:'same-origin'})
    .then(r=>r.json())
    .then(d=>{
      const box = document.getElementById('mensagens');
      if(!box) return;
      let html = '';
      (d.mensagens || []).forEach(m => {
        const isMe = m.remetente_id === uid;
        html += `<div class="mb-2 ${isMe?'msg-entrada':'msg-recebida'}">
          <div class="d-flex justify-content-${isMe?'end':'start'} align-items-start">
            <span class="me-2 msg-bolha nome">${m.nome||'Usuário'}</span>
            <div class="texto">${escHtml(m.msg)}</div>
          </div>
          <small class="${isMe?'text-end':'text-start'} text-white-50">${new Date(m.criado_at).toLocaleTimeString()}</small>
        </div>`;
      });
      box.innerHTML = html;
      box.scrollTop = box.scrollHeight;
    })
    .catch(()=>{});
}

document.querySelectorAll('[data-user-id]').forEach(link=>{
  link.addEventListener('click', e=>{
    e.preventDefault();
    const id = parseInt(link.dataset.userId,10);
    carregarMensagens(id);
    localStorage.setItem('chatUserId', id);
    window.location.href = `usuario.php?id=${id}`;
  });
});

if(userId){
  carregarMensagens(userId);
}

// Enviar mensagem na conversa aberta
const form = document.querySelector('#chatForm');
if(form){
  form.addEventListener('submit', e=>{
    e.preventDefault();
    const v = document.getElementById('novoMsg');
    if(!v.value.trim()){ return; }
    const uid = Number(v.closest('form').querySelector('name')?.value);
    fetch(`chat.php?acao=enviar&id=${uid}&_t=${Date.now()}`, {
      method:'POST',
      credentials:'same-origin',
      body: 'msg='+encodeURIComponent(v.value.trim())
    }).then(()=>{ v.value=''; carregarMensagens(uid); });
  });
}
</script>
</body>
</html>
```

