      $stmt = $pdo->prepare("INSERT INTO usuarios(nome,email,senha_hash) VALUES(:n,:e,:s)");
      $stmt->execute(['n'=>$nome,'e'=>$email,'s'=>$hash]);
      header("location:index.php");
      exit;
    }
  }

  // --- LOGIN ---
  if($_POST['acao'] === 'entrar'){
    $email  = strtolower(trim($_POST['email'] ?? ''));
    $senha  = $_POST['senha'];
    if(empty($email)||empty($senha)){
      $erro = "Informe e-mail e senha.";
    } else {
      $stmt = $pdo->prepare("SELECT * FROM usuarios WHERE email = :e AND ativo = 1");
      $stmt->execute(['e'=>$email]);
      $usu = $stmt->fetch(PDO::FETCH_ASSOC);
      if($usu && password_verify($senha, $usu['senha_hash'])){
        session_start();
        $_SESSION['user_id'] = $usu['id'];
        $_SESSION['nome']    = $usu['nome'];
        $_SESSION['email']   = $usu['email'];
        header("location:chat.php");
        exit;
      }
      $erro = "E-mail ou senha incorretos.";
    }
  }
