<script>
const uid = <?= json_encode(intval($_GET['id'] ?? 0)) ?>;
document.getElementById('uidHidden').value = uid;
const urlBase = window.location.href.replace(/\.php\?.*$/, '.php?');

async function carregar(){
  try{
    const res = await fetch(`${urlBase}?acao=ler&id=${uid}&_t=${Date.now()}`);
    const { mensagens } = await res.json();
    render(mensagens||[]);
  }catch(e){ /* ignora */ }
}

function render(ms){
  const box = document.getElementById('listaLocal');
  box.innerHTML = ms.map((m,i)=>`
    <div class="p-2 rounded ${m.remetente_id===uid?'bg-[#fbbbad].light':'#3a4250'} border border-${m.remetente_id===uid?'var(--amarelo)':'#4a7a96'}">
