      <small>${escHtml(m.msg)}</small><br>
      <small class="text-white-50 fs-7">${new Date(m.criado_at).toLocaleString()}</small>
    </div>`).join('');
  box.classList.remove('d-none');
  box.scrollTop = box.scrollHeight;
}

async function enviar(){
  const v = document.getElementById('campoMsg');
  if(!v.value.trim()) return;
  try{
    await fetch(`usuario.php?acao=enviar&id=${uid}&_t=${Date.now()}`, {
      method:'POST',
      credentials:'same-origin',
      body:'msg='+encodeURIComponent(v.value.trim())
    });
    v.value='';
    carregar();
  }catch(e){ alert('Falhou ao enviar.'); }
}

carregar();
</script>
</body>
</html>
