  .opt-btn.wrong     { border-color: var(--vermelho); background: #fce8e8; }
  .opt-btn.wrong span.x { display: block; color: var(--vermelho); font-weight: 700; font-size: 1.4rem; }
  .span-check { display: none; font-size: 1.4rem; line-height: 1; }

  .btn-next {
    margin-top: 1.3rem; width: 100%; background: var(--azul); color: #fff;
