let indice = 0;
let escolhas = {}; // indice -> letra escolhida
let acertos = 0;
let erros = 0;
const TOTAL = questoes.length;

function iniciar() {
  document.getElementById('tela-inicio').style.display = 'none';
  document.getElementById('tela-prova').style.display = 'block';
  carregar();
}

function carregar() {
  const q = questoes[indice];
  document.getElementById('qAtual').textContent = indice + 1;
  document.getElementById('barProg').style.width = ((indice) / TOTAL * 100) + '%';
  const bloco = document.getElementById('conteudoPergunta');
  bloco.innerHTML = `
    <span class="questao-num">Questão ${indice + 1}</span>
    <p class="enunciado">${q.enunciado}</p>
    <div class="opcoes">
      ${q.alternativas.map(a => `
        <div class="opt-btn" data-letra="${a.letra}" onclick="escolher('${a.letra}')">
          <input type="radio" name="q${indice}" id="opt-${a.letra}">
          <span class="letra">${a.letra}</span>
          <span class="texto">${a.texto}</span>
          <span class="span-check check">✓</span>
          <span class="x">×</span>
        </div>
      `).join('')}
    </div>
  `;
  document.getElementById('btnProxima').textContent = indice === TOTAL - 1 ? 'CONCLUIR &gt;' : 'VER RESPOSTA &gt;';
  document.getElementById('btnProxima').disabled = true;
  resetFeedback();
}

function escolher(letra) {
  const q = questoes[indice];
  const btns = document.querySelectorAll('.opt-btn');
  btns.forEach(b => {
    const l = b.dataset.letra;
    const radio = b.querySelector('input[type=radio]');
    radio.checked = (l === letra);
    if (l === letra) escolhas[indice] = letra;
  });
  document.getElementById('btnProxima').disabled = false;
  mostrarFeedback(q);
}

function mostrarFeedback(q) {
  const escolha = escolhas[indice];
  const btns = document.querySelectorAll('.opt-btn');
  btns.forEach(b => {
    const l = b.dataset.letra;
    const correto = (l === q.alternativas.find(a => a.certo).letra);
    const escolhido = (l === escolha);
    if (l === q.alternativas.find(a => a.certo).letra) b.classList.add('correct');
    else if (escolhido && !correto) b.classList.add('wrong');
  });
  const correta = q.alternativas.find(a => a.certo);
  if (escolha && escolha !== correta.letra) {
    erros++;
  } else if (escolha && escolha === correta.letra) {
    acertos++;
  }
  updateBarra();
}

function resetFeedback() {
  document.querySelectorAll('.opt-btn').forEach(b => {
    b.classList.remove('correct', 'wrong');
    b.querySelector('.span-check').style.display = 'none';
    b.querySelector('.x').style.display = 'none';
    b.querySelector('input[type=radio]').checked = false;
  });
}

function proxima() {
  if (indice < TOTAL - 1) {
    indice++;
    carregar();
  } else {
    mostrarResultado();
  }
}

function atualizarContadores() {
  document.getElementById('acertos').textContent = acertos;
  document.getElementById('erros').textContent = erros;
}

/* ================= RESULTADO ================= */
function mostrarResultado() {
  document.getElementById('tela-prova').style.display = 'none';
  const tela = document.getElementById('tela-result');
  const nota = (acertos / TOTAL) * 20;
  document.getElementById('notaFinal').textContent = nota.toFixed(1);
  document.getElementById('qAtual').textContent = '';

  let faixa, cor;
  if (nota >= 16) { faixa = 'Excelente!'; cor = 'ok'; }
  else if (nota >= 12) { faixa = 'Bom desempenho'; cor = 'med'; }
  else if (nota >= 8) { faixa = 'Regular — revise os pontos abaixo'; cor = 'bad'; }
  else { faixa = 'Abaixo do esperado — estude mais'; cor = 'bad'; }
  document.getElementById('faixaNota').className = `faixa faixa-${cor}`;
  document.getElementById('faixaNota').textContent = faixa;

  const tbody = document.getElementById('corpoResultado');
  tbody.innerHTML = '';
  questoes.forEach((q, i) => {
    const escolh = escolhas[i] || null;
    const certa = q.alternativas.find(a => a.certo).letra;
    const linha = document.createElement('tr');
    linha.innerHTML = `
      <td>${i + 1}</td>
      <td style="max-width:55%; white-space:nowrap;">${escHtml(q.enunciado.slice(0,110))}<br><span style="font-size:.75rem;color:var(--cinza);">${escHtml(q.alternativas[0].texto.slice(0,50))}</span></td>
      <td style="text-align:center;font-weight:700;" ${escolhidaCorreta(i)}>${escolhidaLetra(i)}</td>
      <td style="text-align:center;" ${statusClasse(i)}>${statusTexto(i)}</td>
    `;
    tbody.appendChild(linha);
  });

  const recomendacao = gerarRecomendacao(nota);
  document.getElementById('recomendacao').innerHTML = `<strong>${recomendacao}</strong>`;
}

function escolhidaLetra(i) {
  const l = escolhas[i] || '?';
  return `<span style="color:${l === (questoes[i].alternativas.find(a=>a.certo).letra)?'var(--verde)':'var(--vermelho)'}">${l}</span>`;
}
function statusClasse(i) {
  const ok = escolhas[i] === questoes[i].alternativas.find(a=>a.certo).letra;
  return ok ? 'class="cell-acerto" ✓ Acertou' : 'class="cell-erro" ✗ Errou';
}
function statusTexto(i) {
  return ok ? 'Acerto' : 'Erro';
}
function escHtml(s) { return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
function escolhidaCorreta(i) {
  const l = escolhas[i] || '';
  const certa = questoes[i].alternativas.find(a=>a.certo).letra;
  return l === certa ? '' : 'style="color:var(--vermelho)"';
}

function gerarRecomendacao(nota) {
  if (nota >= 16) return "Parabéns! Você demonstrou excelente domínio do Estatuto. Continue revisando os detalhes menos cobrados.";
  if (nota >= 12) return "Bom resultado! Revise especialmente as questões que errou para consolidar o aprendizado.";
  if (nota >= 8) return "Você precisa reforçar a leitura do Estatuto. Foque em provimento, vacância, deveres, licenças e sanções.";
  return "Desempenho baixo. Recomenda-se ler integralmente o Estatuto, refazer este simulado e resolver provas anteriores da VUNESP.";
}

function reiniciar() {
  escolhas = {};
  acertos = erros = 0;
  indice = 0;
  document.getElementById('tela-result').style.display = 'none';
  document.getElementById('tela-inicio').style.display = 'none';
  document.getElementById('tela-prova').style.display = 'block';
  carregar();
}
</script>
</body>
</html>
